"use client"

import * as React from "react"
import { Sign, type SignProps } from "@/components/ui/sign"
import type { SignShape } from "@/lib/0db/sign-shapes"

const shape: SignShape = {
  "word": "forward",
  "line": [
    [
      [
        "M",
        9,
        18
      ],
      [
        "L",
        15,
        12
      ]
    ],
    [
      [
        "M",
        15,
        12
      ],
      [
        "L",
        9,
        6
      ]
    ]
  ]
}

function SignChevronRightDots(props: Omit<SignProps, "shape" | "variant">) {
  return <Sign shape={shape} variant="dots" {...props} />
}

export { SignChevronRightDots, shape }
